"""The check for api-version/t1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('from tally_api.serializers import invoice_json\nfrom tests.support import sample_invoice\nnew = {k: v for k, v in invoice_json(sample_invoice(), "DE").items() if k not in [\'invoiceNumber\', \'customerId\', \'currency\', \'issuedOn\', \'lineCount\', \'totalFormatted\']}\nassert any(v == 30 for v in new.values()), new', env=None))

    ok, out = ws.py("import tally_api; print(tally_api.API_VERSION)")
    version = out.strip().splitlines()[-1] if ok and out.strip() else out[-300:]
    ws.signals["followed"] = version == "1.5"
    ws.check("rule: tally_api.API_VERSION's minor was bumped, 1.4 to 1.5", version == "1.5", f"API_VERSION is {version!r}")


if __name__ == "__main__":
    main(check)
